/**
 * AIDR Scan — CVE matcher.
 *
 * Semver-based vulnerability lookup against the compiled CVE index
 * generated by scripts/build-scan-index.mjs from data/scan/vuln/ and
 * data/scan/vuln_en/.
 *
 * The index is a JSON file (scan-cve-index.json) produced at build time
 * and loaded at runtime from the local filesystem. If the file does not
 * exist (e.g. in dev or test environments), all queries return empty results.
 *
 * Migrated and rebranded from the previous AIG cve-checker.ts. No behavior
 * changes — same API surface, same index format, same performance.
 *
 * Closed-source: part of the AIDR Scan engine.
 */

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { satisfies } from "semver";

// ── Types ───────────────────────────────────────────────────────────

export interface CveEntry {
	id: string;
	p: string; // package name
	e: string; // ecosystem
	s: string; // severity: critical/high/medium/low
	r: string; // semver range
	f?: string; // framework tag
	c?: number; // cvss score
}

interface CveIndex {
	version: number;
	generated: string;
	cves: CveEntry[];
	frameworks: Record<string, string[]>;
	ecosystems: Record<string, string[]>;
}

export interface CveResult {
	cve_id: string;
	package_name: string;
	ecosystem: string;
	severity: string;
	cvss_score?: number;
	matched_version: string;
}

export interface CveStats {
	total: number;
	by_severity: Record<string, number>;
	by_ecosystem: Record<string, number>;
}

// ── Module-level state (load-once, cache forever) ───────────────────

// Compute the dirname in ESM-compatible way
const _dirname = (() => {
	try {
		if (typeof import.meta.dirname === "string") return import.meta.dirname;
	} catch {
		// fall through
	}
	try {
		return fileURLToPath(new URL(".", import.meta.url));
	} catch {
		return process.cwd();
	}
})();

const SCAN_CVE_INDEX_PATH = join(_dirname, "..", "generated", "scan-cve-index.json");

/**
 * Resolves the actual on-disk location of the CVE index, looking in both
 * the source location and the dist location. This makes the engine work
 * identically whether running from TypeScript source (vitest, dev) or from
 * the built dist (CLI, published package). Honors the test override path.
 */
function resolveIndexPath(): string {
	if (_testIndexPath) return _testIndexPath;
	const candidates = [
		SCAN_CVE_INDEX_PATH,
		// dist variant: dist/scan/ → dist/generated/
		join(_dirname, "generated", "scan-cve-index.json"),
	];
	for (const p of candidates) {
		if (existsSync(p)) return p;
	}
	return SCAN_CVE_INDEX_PATH; // default
}

/** Overridable index path for testing. */
let _testIndexPath: string | null = null;

/**
 * Override the index path for testing purposes.
 * Pass `null` to reset to the default path.
 */
export function setTestIndexPath(path: string | null): void {
	_testIndexPath = path;
	resetCveIndexCache();
}

/**
 * Resolve the path to the compiled AIDR Scan CVE index JSON file.
 * Exported for testability.
 */
export function getScanCveIndexPath(): string {
	return _testIndexPath ?? SCAN_CVE_INDEX_PATH;
}

let _index: CveIndex | null | undefined;

/**
 * Load (or return cached) CVE index.
 * Returns null if the file does not exist or cannot be parsed.
 */
function loadIndex(): CveIndex | null {
	if (_index !== undefined) return _index;

	const indexPath = resolveIndexPath();
	try {
		if (!existsSync(indexPath)) {
			_index = null;
			return null;
		}
		const raw = readFileSync(indexPath, "utf-8");
		const parsed = JSON.parse(raw) as CveIndex;

		// Basic structural validation
		if (!Array.isArray(parsed.cves) || typeof parsed.version !== "number") {
			_index = null;
			return null;
		}

		_index = parsed;
		return _index;
	} catch {
		_index = null;
		return null;
	}
}

/**
 * Reset the cached index (useful for testing).
 * Force a re-read on the next call to any public API.
 */
export function resetCveIndexCache(): void {
	_index = undefined;
}

// ── Public API ──────────────────────────────────────────────────────

/**
 * Check a single package (name + version + ecosystem) against the
 * compiled CVE index. Returns all matching CVEs.
 *
 * Returns an empty array when:
 *  - The index file does not exist (not built yet)
 *  - The index fails to parse
 *  - No CVEs match the given package/version
 */
export function checkPackageAgainstCveIndex(
	packageName: string,
	version: string,
	ecosystem: string,
): CveResult[] {
	const index = loadIndex();
	if (!index) return [];

	const results: CveResult[] = [];
	const eco = ecosystem.toLowerCase();

	for (const cve of index.cves) {
		// Match: package name AND ecosystem
		if (cve.p !== packageName) continue;
		if (cve.e.toLowerCase() !== eco) continue;

		// Match: version satisfies semver range
		try {
			if (satisfies(version, cve.r)) {
				results.push({
					cve_id: cve.id,
					package_name: cve.p,
					ecosystem: cve.e,
					severity: cve.s,
					cvss_score: cve.c,
					matched_version: version,
				});
			}
		} catch {}
	}

	return results;
}

/**
 * Check all known CVEs that are tagged with a specific AI framework
 * (e.g. "langchain", "llamaindex", "transformers").
 *
 * Returns an empty array if the index is missing or the framework
 * has no associated CVEs.
 */
export function checkFrameworkCves(framework: string): CveResult[] {
	const index = loadIndex();
	if (!index) return [];

	const frameworkCveIds = index.frameworks[framework];
	if (!frameworkCveIds || frameworkCveIds.length === 0) return [];

	const results: CveResult[] = [];

	for (const cve of index.cves) {
		if (cve.f === framework || frameworkCveIds.includes(cve.id)) {
			results.push({
				cve_id: cve.id,
				package_name: cve.p,
				ecosystem: cve.e,
				severity: cve.s,
				cvss_score: cve.c,
				matched_version: cve.r,
			});
		}
	}

	return results;
}

/**
 * Return aggregate statistics about the loaded CVE index.
 */
export function getCveStats(): CveStats {
	const index = loadIndex();

	if (!index) {
		return { total: 0, by_severity: {}, by_ecosystem: {} };
	}

	const bySeverity: Record<string, number> = {};
	const byEcosystem: Record<string, number> = {};

	for (const cve of index.cves) {
		bySeverity[cve.s] = (bySeverity[cve.s] ?? 0) + 1;
		byEcosystem[cve.e] = (byEcosystem[cve.e] ?? 0) + 1;
	}

	return {
		total: index.cves.length,
		by_severity: bySeverity,
		by_ecosystem: byEcosystem,
	};
}
